from __future__ import annotations


NATURAL_SUPERNET_HTML = r'''<!doctype html>
<html lang="en" data-alternate-charts="truth-diagonal ellipse-mirror">
<head>
<meta charset="utf-8" />
<meta name="viewport" content="width=device-width,initial-scale=1" />
<title>Supernet · Natural Black Mirror</title>
<style>
:root{color-scheme:dark;--bg:#05070a;--ink:#eff5f7;--muted:#82929d;--line:#24333c;--panel:#0a1015e8;--open:#e0b35a;--mint:#75e0b4;--cyan:#72d8e8;--violet:#b59cff;--red:#ed7b86;--shadow:0 26px 80px #000b;font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}
*{box-sizing:border-box}html,body{width:100%;height:100%;margin:0;overflow:hidden;background:var(--bg);color:var(--ink)}body{background:radial-gradient(circle at 50% 20%,#16252d 0,#091015 36%,#040608 78%)}button,input,textarea{font:inherit;color:inherit}button{cursor:pointer}.shell{height:100%;display:grid;grid-template-rows:58px minmax(0,1fr) 82px}.top{display:flex;align-items:center;gap:12px;padding:0 16px;border-bottom:1px solid var(--line);background:#060a0ed9;backdrop-filter:blur(18px);z-index:20}.brand{min-width:260px}.brand strong{display:block;font-size:15px;letter-spacing:.02em}.brand span{display:block;color:var(--muted);font-size:10px;margin-top:2px}.chart-pill{display:flex;align-items:center;gap:8px;border:1px solid #344853;border-radius:999px;padding:7px 11px;background:#0b141a;font:10px ui-monospace,SFMono-Regular,monospace}.chart-dot{width:8px;height:8px;border-radius:50%;background:var(--open);box-shadow:0 0 15px #e0b35a88}.top-spacer{flex:1}.top button,.bottom button,.drawer button{border:1px solid #334751;border-radius:10px;background:#101a20;padding:8px 10px;font-weight:650}.top button.primary,.bottom button.primary{background:#eaf4f4;color:#061013;border-color:#eaf4f4}.live{font-size:10px;color:#9db0b9;display:flex;align-items:center;gap:6px}.live i{width:7px;height:7px;border-radius:50%;background:var(--mint);box-shadow:0 0 13px #75e0b4}.main{min-height:0;display:grid;grid-template-columns:minmax(0,1fr) 330px}.mirror{position:relative;overflow:hidden}.mirror svg{width:100%;height:100%;display:block;touch-action:none}.grid{stroke:#26343d;stroke-opacity:.22}.edge{stroke:#708691;stroke-width:1.4;stroke-opacity:.62;fill:none}.edge.causal{stroke:var(--cyan)}.edge.OPEN{stroke:var(--open)}.node circle{fill:#111d24;stroke:#9eb4bf;stroke-width:1.5;filter:url(#shadow)}.node.OPEN circle{stroke:var(--open)}.node.selected circle{stroke:white;stroke-width:3;filter:url(#glow)}.node text{fill:#e7f0f3;font-size:10px;text-anchor:middle;paint-order:stroke;stroke:#05080b;stroke-width:4;pointer-events:none}.node .sub{fill:#91a3ad;font-size:8px}.closure-ring{fill:none;stroke-width:2}.ring-deriv{stroke:var(--cyan)}.ring-admits{stroke:var(--open)}.ring-balance{stroke:var(--violet)}.ring-meta{stroke:var(--mint)}.axis{stroke:#7ba1ad;stroke-width:2;marker-end:url(#arrow)}.hair{stroke:var(--open);stroke-width:2;stroke-dasharray:5 7}.ball{fill:#72d8e814;stroke:#72d8e877;stroke-width:2}.mirror-label{fill:#cbd8dd;font:11px ui-monospace,SFMono-Regular,monospace;text-anchor:middle}.hud{position:absolute;left:14px;top:14px;max-width:min(520px,70%);border:1px solid #31434d;border-radius:14px;background:#070d12df;backdrop-filter:blur(16px);padding:11px 13px;box-shadow:var(--shadow)}.hud h1{font-size:18px;margin:0 0 4px}.hud p{font-size:11px;line-height:1.5;color:#9dafb8;margin:0}.hud .why{color:#d8e5e9;margin-top:7px}.hud .tags{display:flex;gap:5px;flex-wrap:wrap;margin-top:8px}.tag{font:9px ui-monospace,SFMono-Regular,monospace;border:1px solid #3b4f59;border-radius:999px;padding:3px 6px;color:#aec1c9}.stage{position:absolute;left:14px;bottom:14px;border:1px solid #2e414a;background:#070d12df;border-radius:11px;padding:8px 10px;color:#91a4ae;font:9px ui-monospace,SFMono-Regular,monospace}.drawer{border-left:1px solid var(--line);background:var(--panel);backdrop-filter:blur(18px);overflow:auto}.block{padding:14px;border-bottom:1px solid #202e35}.block h2{font-size:10px;letter-spacing:.12em;text-transform:uppercase;color:#8ea0aa;margin:0 0 10px}.source{white-space:pre-wrap;font-size:12px;line-height:1.5;padding:10px;border:1px solid #293941;border-radius:10px;background:#060a0d;margin:7px 0}.kv{display:grid;grid-template-columns:92px 1fr;gap:5px 8px;font-size:10px}.kv dt{color:#80929c}.kv dd{margin:0;overflow-wrap:anywhere}.layers{display:flex;flex-direction:column;gap:6px}.layer{border:1px solid #2d4049;border-radius:9px;padding:8px;background:#0b1318;font-size:11px}.layer.hidden-layer{border-style:dashed;color:#788992}.actions{display:flex;gap:6px;flex-wrap:wrap}.actions button{font-size:10px;padding:7px 8px}.actions button[disabled]{opacity:.35;cursor:not-allowed}.bottom{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:10px;padding:11px 14px;border-top:1px solid var(--line);background:#070c10e8;backdrop-filter:blur(16px)}.composer{display:grid;grid-template-columns:130px 120px minmax(180px,1fr);gap:8px}.composer input,.composer textarea{border:1px solid #30434c;border-radius:10px;background:#081014;padding:9px}.composer textarea{resize:none;height:58px}.bottom-actions{display:flex;align-items:center;gap:7px}.empty{display:grid;place-items:center;height:100%;color:#83949d}.toast{position:fixed;left:50%;bottom:96px;transform:translateX(-50%);background:#101b20;border:1px solid #3a515c;border-radius:10px;padding:10px 14px;font-size:11px;opacity:0;pointer-events:none;transition:.2s;z-index:50}.toast.show{opacity:1}.toast.error{border-color:#8a454e;color:#ffadb5}@media(max-width:900px){.main{grid-template-columns:1fr}.drawer{position:absolute;right:0;top:58px;bottom:82px;width:min(350px,92vw);transform:translateX(100%);transition:.2s;z-index:15;box-shadow:var(--shadow)}.drawer.open{transform:none}.brand{min-width:180px}.composer{grid-template-columns:90px minmax(120px,1fr)}.composer textarea{grid-column:1/-1}.bottom{grid-template-columns:1fr auto}.chart-pill{display:none}}@media(max-width:620px){.brand span{display:none}.top{padding:0 9px}.main{grid-template-columns:1fr}.composer{grid-template-columns:1fr}.composer textarea{grid-column:auto}.bottom{height:auto;grid-template-columns:1fr}.shell{grid-template-rows:54px minmax(0,1fr) 188px}.drawer{top:54px;bottom:188px}.hud{max-width:calc(100% - 28px)}.top .classic{display:none}}
</style>
</head>
<body>
<div class="shell">
<header class="top"><div class="brand"><strong>Supernet · Natural Black Mirror</strong><span>One continuous integrator · chart selected by current closure receipts</span></div><div class="chart-pill"><i class="chart-dot"></i><span id="chartKind">OPEN FIELD</span></div><div class="top-spacer"></div><div class="live"><i></i><span id="liveText">live</span></div><button class="classic" onclick="location.href='/supernet/classic'">Rechart</button><button id="drawerToggle">Fiber</button></header>
<section class="main">
<main class="mirror"><svg id="mirror" viewBox="-700 -430 1400 860" aria-label="Natural closure interface"><defs><filter id="shadow" x="-60%" y="-60%" width="220%" height="220%"><feDropShadow dx="0" dy="5" stdDeviation="7" flood-color="#000" flood-opacity=".75"/></filter><filter id="glow" x="-100%" y="-100%" width="300%" height="300%"><feGaussianBlur stdDeviation="7" result="b"/><feMerge><feMergeNode in="b"/><feMergeNode in="SourceGraphic"/></feMerge></filter><marker id="arrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="6" markerHeight="6" orient="auto"><path d="M0 0L10 5L0 10z" fill="#7ba1ad"/></marker><pattern id="grid" width="48" height="48" patternUnits="userSpaceOnUse"><path d="M48 0H0V48" class="grid" fill="none"/></pattern></defs><rect x="-4000" y="-4000" width="8000" height="8000" fill="url(#grid)"/><g id="world"></g></svg><div class="hud"><h1 id="chartTitle">Open field</h1><p id="axiometric">No point has entered.</p><p class="why" id="why"></p><div class="tags" id="tags"></div></div><div class="stage" id="stage">OPEN · no canonical presentation</div></main>
<aside class="drawer" id="drawer"><section class="block"><h2>Exact source fiber</h2><div id="sources"></div></section><section class="block"><h2>Required layers</h2><div class="layers" id="layers"></div></section><section class="block"><h2>Closure receipt</h2><dl class="kv" id="receipt"></dl></section><section class="block"><h2>Actions admitted now</h2><div class="actions" id="actions"></div><p style="font-size:9px;color:#7e909a;margin:10px 0 0">Rigidify, truth-diagonal, and ellipse-mirror remain available only as receipt-supported or manual rechartings; they never become new fields.</p></section></aside>
</section>
<footer class="bottom"><div class="composer"><input id="author" value="participant" aria-label="Author"/><input id="form" value="note" aria-label="Form"/><textarea id="text" placeholder="Offer a note, problem, proof, interaction, sensor return, or form not yet named…"></textarea></div><div class="bottom-actions"><button id="integrate" class="primary">Integrate</button><button id="interact">Interact</button><button id="admit">Admit view</button></div></footer>
</div><div class="toast" id="toast"></div>
<script>
const NS='http://www.w3.org/2000/svg';
let focus=null, receipt=null, socket=null, timer=null;
const $=id=>document.getElementById(id);
function toast(message,error=false){const el=$('toast');el.textContent=message;el.className='toast show'+(error?' error':'');clearTimeout(timer);timer=setTimeout(()=>el.className='toast',2600)}
async function api(url,options={}){const response=await fetch(url,{headers:{'content-type':'application/json',...(options.headers||{})},...options});if(!response.ok){let detail=response.statusText;try{detail=(await response.json()).detail||detail}catch{}throw new Error(detail)}return response.headers.get('content-type')?.includes('json')?response.json():response.text()}
function esc(value){return String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function svg(name,attrs={}){const el=document.createElementNS(NS,name);for(const [key,value] of Object.entries(attrs))el.setAttribute(key,String(value));return el}
function positionMap(topology){const explicit=topology.positions||{};const nodes=topology.nodes||[];nodes.forEach((node,index)=>{if(!explicit[node.id]){const a=2*Math.PI*index/Math.max(1,nodes.length);explicit[node.id]={x:430*Math.cos(a),y:290*Math.sin(a)}}});return explicit}
function label(node){return node.form_label||node.label||node.authored_by||node.id.slice(0,8)}
function renderGeneric(topology){const world=$('world');const positions=positionMap(topology);for(const edge of topology.edges||[]){const a=positions[edge.source],b=positions[edge.target];if(!a||!b)continue;world.append(svg('line',{x1:a.x,y1:a.y,x2:b.x,y2:b.y,class:`edge ${edge.kind||''} ${edge.verdict||''}`}))}for(const node of topology.nodes||[]){const p=positions[node.id];const g=svg('g',{class:`node ${node.current_verdict||node.verdict||'OPEN'} ${focus===node.id?'selected':''}`,transform:`translate(${p.x} ${p.y})`});g.append(svg('circle',{r:focus===node.id?29:22}));const t=svg('text',{y:-2});t.textContent=label(node).slice(0,28);g.append(t);const s=svg('text',{y:12,class:'sub'});s.textContent=`${node.authored_by||''} · ${node.current_stage||''}`;g.append(s);g.addEventListener('click',()=>{focus=node.id;refresh()});world.append(g)}}
function overlayProof(){const world=$('world');const rings=[[62,'ring-deriv','Deriv'],[98,'ring-admits','Admits'],[136,'ring-balance','Balance'],[178,'ring-meta','MetaAbs']];for(const [r,cls,name] of rings){world.append(svg('circle',{cx:0,cy:0,r,class:`closure-ring ${cls}`}));const t=svg('text',{x:0,y:-r+14,class:'mirror-label'});t.textContent=name;world.append(t)}}
function overlayTuring(life){const world=$('world');const points=[[-330,0,'H₀','global hair · executor'],[0,0,'B∞','local ball · reactor'],[330,0,'H₀⁺','return · continuation']];world.append(svg('line',{x1:-280,y1:0,x2:-55,y2:0,class:'axis'}));world.append(svg('line',{x1:55,y1:0,x2:280,y2:0,class:'axis'}));for(const [x,y,name,sub] of points){const g=svg('g',{transform:`translate(${x} ${y})`});g.append(svg('circle',{r:name==='B∞'?72:52,class:name==='B∞'?'ball':''}));const t=svg('text',{y:-3,class:'mirror-label'});t.textContent=name;g.append(t);const s=svg('text',{y:17,class:'mirror-label'});s.textContent=sub;g.append(s);world.append(g)}if(!life?.translational_truth_receipt?.complete){const h=svg('text',{x:0,y:118,class:'mirror-label'});h.textContent='internal / external / actual / potential remain undefined';world.append(h)}}
function overlayReturn(){const world=$('world');world.append(svg('circle',{cx:0,cy:0,r:120,class:'ball'}));for(let i=0;i<9;i++){const a=2*Math.PI*i/9;world.append(svg('line',{x1:120*Math.cos(a),y1:120*Math.sin(a),x2:235*Math.cos(a),y2:235*Math.sin(a),class:'hair'}))}}
function render(){if(!receipt)return;const world=$('world');world.replaceChildren();const chart=receipt.natural_chart;const topology=receipt.topology||{};$('chartKind').textContent=chart.kind.replaceAll('_',' ');$('chartTitle').textContent=chart.title;$('axiometric').textContent=chart.axiometric_reading;$('why').textContent=chart.selection_reason;$('stage').textContent=`${receipt.focus_event?.current_stage||'OPEN'} · ${receipt.focus_event?.current_verdict||'OPEN'} · no canonical pixel layout`;$('tags').innerHTML=[chart.topology_mode,chart.lens,'minimal sufficient','OPEN'].map(x=>`<span class="tag">${esc(x)}</span>`).join('');
if(chart.kind==='TURING_BEING')overlayTuring(receipt.turing_being_depth);else{renderGeneric(topology);if(chart.kind==='PROOF_BALANCE')overlayProof();if(chart.kind==='RETURN_BALL_HAIR')overlayReturn()}
const sources=receipt.source_fibre||[];$('sources').innerHTML=sources.length?sources.map(source=>`<div class="source">${esc(source.exact_text||source.id)}</div>`).join(''):'<div class="source">The field is empty. Integration creates the first exact source.</div>';
$('layers').innerHTML=[...(chart.required_layers||[]).map(x=>`<div class="layer">${esc(x)}</div>`),...(chart.hidden_until_receipt||[]).map(x=>`<div class="layer hidden-layer">${esc(x)} · hidden until receipt</div>`)].join('');
const ar=receipt.admission_receipt;$('receipt').innerHTML=Object.entries(ar).map(([k,v])=>`<dt>${esc(k)}</dt><dd>${esc(v)}</dd>`).join('');
const names={integrate:'Integrate',interact:'Interact',relate:'Relate',rigidify:'Rigidify','return-reaction':'Return reaction',return:'Return',reopen:'Reopen','admit-interface':'Admit view'};$('actions').innerHTML=(chart.available_actions||[]).map(name=>`<button data-action="${esc(name)}">${names[name]||name}</button>`).join('');$('actions').querySelectorAll('button').forEach(button=>button.addEventListener('click',()=>runAction(button.dataset.action)));$('interact').disabled=!focus}
async function refresh(){try{const params=new URLSearchParams();if(focus)params.set('focus_event_id',focus);receipt=await api('/supernet/interface?'+params);focus=receipt.focus_event?.id||null;render();$('liveText').textContent='live'}catch(error){toast(error.message,true);$('liveText').textContent='offline'}}
async function integrate(parent=false){const text=$('text').value.trim();if(!text)return toast('Enter an exact source',true);const body={exact_text:text,authored_by:$('author').value||'participant',form_label:$('form').value||'note',affected_perspectives:[],relation_hints:[]};const path=parent&&focus?`/supernet/events/${focus}/interact`:'/supernet/integrate';try{const result=await api(path,{method:'POST',body:JSON.stringify(body)});focus=result.event_id;$('text').value='';toast(parent?'Interaction returned':'Source integrated');await refresh()}catch(error){toast(error.message,true)}}
async function runAction(action){if(action==='integrate')return integrate(false);if(action==='interact')return integrate(true);if(action==='admit-interface'){try{const result=await api('/supernet/interface/admissions',{method:'POST',body:JSON.stringify({focus_event_id:focus,authored_by:$('author').value||'participant'})});toast('Natural chart admitted into closure');focus=result.event.id;return refresh()}catch(error){return toast(error.message,true)}}if(action==='return'){const text=prompt('Exact returned form');if(!text||!focus)return;try{await api(`/supernet/events/${focus}/return`,{method:'POST',body:JSON.stringify({actor_id:$('author').value||'participant',exact_text:text,form_label:'returned form'})});toast('Return entered the field');return refresh()}catch(error){return toast(error.message,true)}}if(action==='reopen'){const reason=prompt('Why does this relation reopen?');if(!reason||!focus)return;try{await api(`/supernet/events/${focus}/reopen`,{method:'POST',body:JSON.stringify({actor_id:$('author').value||'participant',reason})});toast('Relation reopened');return refresh()}catch(error){return toast(error.message,true)}}if(action==='rigidify')return toast('Use the selected event’s admissibility relation; manual chart available under Rechart.');if(action==='return-reaction')return toast('Open the Turing Being fiber to submit the source-preserving reaction return.');if(action==='relate')return toast('Select the relation endpoints in the full rechart surface.');}
$('integrate').onclick=()=>integrate(false);$('interact').onclick=()=>integrate(true);$('admit').onclick=()=>runAction('admit-interface');$('drawerToggle').onclick=()=>$('drawer').classList.toggle('open');
function connect(){try{socket=new WebSocket(`${location.protocol==='https:'?'wss':'ws'}://${location.host}/supernet/stream`);socket.onmessage=()=>refresh();socket.onclose=()=>setTimeout(connect,1600);socket.onerror=()=>socket.close()}catch{setTimeout(connect,1600)}}
refresh();connect();setInterval(refresh,6000);
</script>
</body>
</html>'''
